tools.example:
model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
// GUI: Solid Mechanics (solid) > right-click > Material Models > Hyperelastic Material,
// select the rubber domain, choose Material model = Mooney-Rivlin, two parameters,
// and enter C10, C01 and the bulk modulus.
model.study("std1").feature("stat").set("geometricNonlinearity", true);

model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
// GUI: Solid Mechanics (solid) > Linear Elastic Material 1 > right-click > Plasticity,
// set Initial yield stress = 250[MPa] and Isotropic hardening model = Linear, E_Tiso = 2[GPa].
model.study("std1").create("param", "Parametric");

model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
// GUI: Solid Mechanics (solid) > right-click > Prescribed Displacement,
// select boundary 6, tick "Prescribed in z direction" and enter u0z = -0.5[mm].
model.component("comp1").physics("solid").create("fix1", "Fixed", 2);
model.component("comp1").physics("solid").feature("fix1").selection().set(new int[]{1});

model.component("comp1").geom("geom1").feature("fin").set("action", "assembly");
model.component("comp1").geom("geom1").run();
model.component("comp1").pair().create("p1", "Contact");
model.component("comp1").pair("p1").source().set(new int[]{5});
model.component("comp1").pair("p1").destination().set(new int[]{9});
model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
// GUI: Solid Mechanics (solid) > right-click > Pairs > Contact, then select Contact Pair 1.

model.component("comp1").physics().create("spf", "LaminarFlow", "geom1");
model.component("comp1").physics().create("ht", "HeatTransfer", "geom1");
// GUI: Heat Transfer (ht) > right-click > Fluid, select the channel domain,
// and set Velocity field = Velocity field (spf).
model.component("comp1").multiphysics().create("nitf1", "NonIsothermalFlow", "geom1", 3);

model.component("comp1").physics().create("ht", "HeatTransfer", "geom1");
// GUI: Add Physics > Heat Transfer > Radiation > Surface-to-Surface Radiation (rad),
// select the cavity boundaries, then add the Heat Transfer with Surface-to-Surface Radiation
// multiphysics coupling so that rad supplies the radiative flux to ht.
model.study("std1").create("stat", "Stationary");

model.component("comp1").physics().create("spf", "LaminarFlow", "geom1");
model.component("comp1").physics("spf").feature("wallbc1").set("BoundaryCondition", "NoSlip");
// GUI: Laminar Flow (spf) > right-click > Wall, select the moving surface,
// and set Boundary condition = Moving wall with a translational velocity.

model.component("comp1").physics().create("dl", "DarcysLaw", "geom1");
// GUI: Darcy's Law (dl) > Porous Medium 1 - set permeability and porosity;
// right-click > Pressure to prescribe p on the inlet face and > Mass Flux for a specified flux.
model.study("std1").create("stat", "Stationary");

model.component("comp1").physics().create("spf", "LaminarFlow", "geom1");
model.component("comp1").physics().create("ls", "LevelSet", "geom1");
// GUI: Multiphysics > Two-Phase Flow, Level Set - pick spf as Fluid flow interface
// and ls as the Moving interface, then set the two fluids' densities, viscosities
// and the surface tension coefficient.
model.study("std1").create("time", "Transient");
